def squash(s: str) -> str:
    def esc(c: str) -> str:
        return "\\" + c if c.isdigit() or c == "\\" else c

    result = []
    i = 0
    n = len(s)

    while i < n:
        j = i + 1
        while j < n and s[j] == s[i]:
            j += 1

        length = j - i
        encoded = esc(s[i])

        if length >= 3:
            result.append(str(length))
            result.append(encoded)
        else:
            result.append(encoded * length)

        i = j

    return "".join(result)
